    ["<Assistant_Title1>Golden Legend</>\n<Assistant_Title2>Achievement Category: </>Growth - Equipment\n<Assistant_Title2>Unlock Condition: </>Equip 8 items of Gold quality or higher"] = "<Assistant_Title1>Золотая легенда</>\n<Assistant_Title2>Категория достижения: </>Разработка-оборудование\n<Assistant_Title2>Условия разблокировки: </>Наденьте 8 предметов золотого качества и выше.",
    ["Highest winning streak"] = "Самая высокая победная серия",
